  echo_gloom_mossroot_title: 'The Moss Scroll',
  echo_gloom_mossroot_desc: 'Moss crept up the base of the stones into a single scroll - it can only be read at dawn, and only by the sleepless.',
  echo_gloom_lamproad_title: "The Lamp-Road's End",
  echo_gloom_lamproad_desc: 'The one who carries a lantern deeper into the mist without ever turning back - his road has no end, for no one remembers his name.',
  echo_gloom_newknot_title: 'One More Knot',
  echo_gloom_newknot_desc: 'The strips of cloth always end with one more knot - the tree never granted a single wish, yet the queue of those who tie grows longer every year.',
