  quest_journal_default_text: 'A new mission on the planes has begun.',

  // Zone identity triple (W-D2 slice 16i: name / subtitle / description)
  zone_name_hub: 'Crossing Hub',
  zone_name_fantasy: 'Greywhite Forest',
  zone_name_magic: 'Hogwarts Ruins',
  zone_name_space: "Miller's Wastes",
  zone_name_void: 'Broken Timeline',
  zone_name_abyss: 'Chaos Border',
  zone_name_gloom: 'Gloomy Woodland',
  zone_name_radiant: 'Radiant Sanctuary',
  zone_name_corridor: 'Inter-plane Corridor',
  zone_subtitle_hub: 'Center of the Planes',
  zone_desc_hub: 'Three ancient paths lead to different plane fragments. The World Anchor flickers here, waiting to be repaired.',
  zone_subtitle_fantasy: 'Middle-earth Ruins · Lord of the Rings',
  zone_desc_fantasy: "An ancient elven forest covers the gentle slopes of the Greywhite mountains. Fallen pillars tell of a lost civilization. Legend says a fragment of the World Anchor sleeps beneath the One Ring.",
  zone_subtitle_magic: 'Magic Plane · Harry Potter',
  zone_desc_magic: "The ruins of a magic academy float in the night sky. Moving staircases, drifting candles, unicorn whispers deep in the forbidden forest. The laws of space and time differ here.",
  zone_subtitle_space: 'Stellar Plane · Interstellar',
  zone_desc_space: 'A wasteland warped by gravity anomalies. A huge black hole lens hangs in the sky, ice clouds flow across the ground. Legend says the five-dimensional bookshelf lies here, recording the fate of every plane.',
  zone_subtitle_void: 'Fourth Plane · Rift of Time',
  zone_desc_void: 'A hidden plane revealed only after the World Anchor ascends. Golden time rings float in the void, past and future overlap. The Void Chronarch guards the Fourth Fragment.',
  zone_subtitle_abyss: "Fifth Plane · The Rift Between Worlds",
  zone_desc_abyss: "After the four fragments were reforged, the edges of the planes still leak chaotic energy. Lava and ice coexist here — the ultimate place to test a traveler's weapon skill tree.",
  zone_subtitle_gloom: 'Darkwood Forest · Realm of Mist',
  zone_desc_gloom: 'Everlasting mist shrouds the twisted trees. There is no sunlight here — only faint glowing moss to guide the way.',
  zone_subtitle_radiant: 'Golden Sand Sanctuary · Land of Dawn',
  zone_desc_radiant: 'A magnificent palace built of flowing golden sand. At first light, the whole city glows.',
  zone_subtitle_corridor: 'Between the Planes',
  zone_desc_corridor: 'A bare corridor between fragments, where wind takes the place of a zone theme.',
  rest_point_campfire_name: '${zone} Campfire',
  rest_point_name_hub: 'World Anchor Rest Point',

  // 两座后期副本守钥者台词（此前一句都没有）
  boss_dungeon_gloom_mist_crypt_intro: "Mist pours up from the depths of the crypt — the warden opens its eyes inside the fog.",
  boss_dungeon_gloom_mist_crypt_p2: "Something in the mist wakes — the warden is no longer only a warden.",
  boss_dungeon_gloom_mist_crypt_defeat: "The mist clears. The shadow of a fragment shows deep in the crypt.",
  boss_dungeon_radiant_dawn_hall_intro: "Dawn light falls from the vault — the warden raises the Key of the Hub.",
  boss_dungeon_radiant_dawn_hall_p2: "The hall's light turns white — the warden's shadow begins to split.",
  boss_dungeon_radiant_dawn_hall_defeat: "The hall falls quiet. The fragment behind the door is still warm.",

  // 副本守钥者第三阶段（补两座）
  boss_dungeon_gloom_mist_crypt_p3: "The mist swallows the lamps — the warden's outline shifts behind the fog.",
  boss_dungeon_radiant_dawn_hall_p3: "The hall's gold compresses into a single white line — this time its shadow stands taller than it does.",

  // 副本守钥者第三阶段（W-D2 / W-E3 切片5）
  boss_dungeon_ruin_crypt_p3: "The tomb warden calls up every dead soul — the gravestones begin to move.",
  boss_dungeon_forbidden_library_p3: "The page-keeper tears the forbidden book open — the loose pages chase you.",
  boss_dungeon_five_dim_rift_p3: "The supervisor twists the geometry — the room begins to fold.",
  boss_dungeon_forest_shrine_p3: "The ancient tree's roots break the surface — the warden no longer holds a fixed shape.",
  boss_dungeon_hub_catacombs_p3: "The Key of the Hub begins to resonate — the walls of the crypt shift.",
  boss_dungeon_phase3_banner: "Key Warden · Phase III",

  // 秘典文案（W-D2 切片16w）
  codex_anchor_title: "World Anchor",
  codex_anchor_text: "The stable point where the three realms meet. The anchor flame is not wood — it is the afterglow of planes grinding together.",
  codex_walker_title: "Plane Walker",
  codex_walker_text: "A stitcher who crosses the grey woods, the ruins and the wastes — not a tourist, but one who repairs rifts.",
  codex_shadow_text: "The red ring east of the Greywhite Forest. Two phases: roll before the slam, parry to trigger a fatal counter.",
  codex_mage_title: "Archmagus Saloran",
  codex_mage_text: "Homing purple orbs — parry at close range to interrupt. In phase two the orbs speed up.",
  codex_singularity_text: "The core of the gravity well on Miller's Wastes. Three phases of orbital barrage — keep moving, charge to break the shield.",
  codex_void_title: "Void Chronarch",
  codex_void_text: "A hidden boss. A charged spell breaks the time stop — not one of the three main-line bosses.",
  codex_chaos_title: "Chaos Rift Lord",
  codex_chaos_text: "The final trial in three phases. The chaos pulse scorches anything close — switch sword and staff, and max the skill tree.",
  codex_execution_text: "A heavy strike on a full posture bar triggers the orbital slow motion. Press {escape} to skip the cutscene.",
  codex_finisher_text: "The third hit of a combo locks onto the target — the camera pushes in and time scales.",
  codex_rematch_text: "After beating a boss, press {interact} at its beacon to summon a rematch. It tops up soulfire without advancing the main line.",
  codex_cg_title: "CG Gallery",
  codex_cg_text: "Campfire branches, boss takedowns and combat memories unlock illustrations — the CG Gallery tab lives under the {journal} key.",
  codex_dungeon_title: "Maze Lore",
  codex_dungeon_text: "Stele fragments go into the journal. After Chapter 5 the dungeons can be re-challenged with random layouts.",
  codex_zone_space_label: "Wastes",
  codex_zone_combat_label: "Combat",
  codex_zone_dungeon_label: "Dungeon",
  journal_tab_lore_codex: "Plane Codex · {journal} to close",
  codex_stats: "Collected ${unlocked} / ${total} (${percent}%)",
  codex_locked_hint: "Keep exploring, talk at campfires and defeat bosses to unlock",

