  // Boss 台词与副本守钥者文案（W-D2 切片16u）
  boss_phase_shadow_warden_p1_banner: "Phase I · Shadow Judgment",
  boss_phase_shadow_warden_p1_toast: "\"Those who set foot in the shadow realm will face a threefold judgment.\"",
  boss_phase_shadow_warden_p2_banner: "Phase II · Sundering Earth",
  boss_phase_shadow_warden_p2_toast: "\"The ground will betray you too — dodge the red ring!\"",
  boss_phase_shadow_warden_p3_banner: "Phase III · Fury",
  boss_phase_shadow_warden_p3_toast: "\"The shadow realm will not let any traverser go!\"",
  boss_phase_archmagus_p1_banner: "Phase I · Arcane Veil",
  boss_phase_archmagus_p1_toast: "\"Light and planes alike — devoured by me.\"",
  boss_phase_archmagus_p2_banner: "Phase II · Barrage",
  boss_phase_archmagus_p2_toast: "\"Dodge the purple orbs — parry only at close range!\"",
  boss_phase_archmagus_p3_banner: "Phase III · Forbidden Words",
  boss_phase_archmagus_p3_toast: "\"The last page must not be read!\"",
  boss_phase_singularity_herald_p1_banner: "Phase I · Gravity Well",
  boss_phase_singularity_herald_p1_toast: "\"Mass is fate. You cannot escape it.\"",
  boss_phase_singularity_herald_p2_banner: "Phase II · The Pull",
  boss_phase_singularity_herald_p2_toast: "\"Feel the singularity — do not let it pull you to the center!\"",
  boss_phase_singularity_herald_p3_banner: "Phase III · Orbital Barrage",
  boss_phase_singularity_herald_p3_toast: "\"Six orbits, six dead ends.\"",
  boss_phase_void_chronarch_p1_banner: "Phase I · Timeline",
  boss_phase_void_chronarch_p1_toast: "\"By the time you read this, another you has already fallen.\"",
  boss_phase_void_chronarch_p2_banner: "Phase II · Time Stop",
  boss_phase_void_chronarch_p2_toast: "\"Time folds here — a charged spell can break it!\"",
  boss_phase_void_chronarch_p3_banner: "Phase III · Final Hour",
  boss_phase_void_chronarch_p3_toast: "\"All timelines converge — only cutting through remains.\"",
  boss_phase_chaos_overlord_p1_banner: "Phase I · The Rift",
  boss_phase_chaos_overlord_p1_toast: "\"The four realms are one, yet the rift remains.\"",
  boss_phase_chaos_overlord_p2_banner: "Phase II · Chaos Pulse",
  boss_phase_chaos_overlord_p2_toast: "\"Come close and chaos will burn you — keep your distance!\"",
  boss_phase_chaos_overlord_p3_banner: "Phase III · Finality",
  boss_phase_chaos_overlord_p3_toast: "\"Cut me apart, or become the next rift.\"",
  boss_defeat_shadow_warden_text: "The shadows scatter. The first chain on the Greywhite Forest is broken.\n\nThe campfire can now unlock the sword skill \"Shadow Cut\".",
  boss_defeat_archmagus_text: "The forbidden book closes. The arcane storm over the Hogwarts Ruins subsides.\n\nThe staff skill \"Arcane Resonance II\" is now available at the campfire.",
  boss_defeat_singularity_herald_text: "The gravity well collapses. Miller's Wastes falls still again.\n\nThe sword skill \"Plane Slash Mastery\" has been unlocked.",
  boss_defeat_void_chronarch_text: "The timeline sews itself shut. You watch countless reflections of yourself fade away.\n\nThe staff skill \"Chrono Insight\" has been unlocked.",
  boss_defeat_chaos_overlord_text: "Chaos withdraws. The lightning along the border falls silent.\n\nThe dual-style ultimate \"Endless Walker\" has been unlocked.",
  boss_dungeon_ruin_crypt_intro: "The ruins' tomb warden rises from the inscriptions.",
  boss_dungeon_ruin_crypt_p2: "The warden wakes the ruins' dead — faster, and fiercer.",
  boss_dungeon_ruin_crypt_defeat: "The tomb falls silent. An anchor fragment shows behind the wall.",
  boss_dungeon_forbidden_library_intro: "The forbidden book's page-keeper takes on the name of ten thousand volumes.",
  boss_dungeon_forbidden_library_p2: "The last page begins to burn — the page-keeper goes berserk.",
  boss_dungeon_forbidden_library_defeat: "The forbidden book closes. The library's disaster is postponed.",
  boss_dungeon_five_dim_rift_intro: "The rift supervisor descends from a five-dimensional projection.",
  boss_dungeon_five_dim_rift_p2: "Geometry twists — the supervisor enters hunting mode.",
  boss_dungeon_five_dim_rift_defeat: "The projection dissolves. The rift observation station regains signal.",
  boss_dungeon_forest_shrine_intro: "The roots of the shrine's ancient tree become the key warden.",
  boss_dungeon_forest_shrine_p2: "The roots coil around — the warden enters its second phase.",
  boss_dungeon_forest_shrine_defeat: "The memory of the last era scatters with the wind.",
  boss_dungeon_hub_catacombs_intro: "The hub key warden awakens from the deepest catacombs.",
  boss_dungeon_hub_catacombs_p2: "The warden draws the Key of the Hub — the maze trembles.",
  boss_dungeon_hub_catacombs_defeat: "The warden falls. The depths beneath the hub seal themselves again.",
  boss_dungeon_phase1_banner: 'Key Warden · Phase I',
  boss_dungeon_phase2_banner: 'Key Warden · Phase II',
  boss_dungeon_defeat_banner: 'The Key Warden has fallen',
  boss_dungeon_void_broken_casket_intro: 'The casket lid flies open — the clock inside is still running.',
  boss_dungeon_void_broken_casket_p2: 'The ticking quickens — the shadows in the casket begin to overlap.',
  boss_dungeon_void_broken_casket_p3: 'The casket walls close in — the warden squeezes out through the seam.',
  boss_dungeon_void_broken_casket_defeat: 'The clock stops. The lid shuts, leaving only a broken scale inside.',
  boss_dungeon_abyss_deep_maw_intro: 'Grinding rises from below — the deep maw opens.',
  boss_dungeon_abyss_deep_maw_p2: "The maw closes halfway — the warden's teeth grind.",
  boss_dungeon_abyss_deep_maw_p3: 'The whole border caves inward — the warden swallows its last breath.',
  boss_dungeon_abyss_deep_maw_defeat: 'Silence below. The jaw-bone is wedged in the rock, still open.',
  boss_dungeon_sunless_oratory_intro: 'The pews are empty — the vigil walks up from the last row.',
  boss_dungeon_sunless_oratory_p2: 'Half the lamp-stands topple — it blows each dead wick alight.',
  boss_dungeon_sunless_oratory_p3: "The nave's vault cracks and no light comes in — the vigil steps beneath the crack.",
  boss_dungeon_sunless_oratory_defeat: 'The vigil kneels back in the last row. The lamps stay unlit, but the oratory is quiet.',
  boss_phase_fallback_banner: 'Phase ${phase}',
  boss_phase_fallback_toast: 'Boss phase ${phase}!',

