  // 支线任务文案（W-D2 切片16k：标题/描述/日志全是键）
  sq_side_wisp_12_title: "Soulfire Wisp Hunter",
  sq_side_wisp_12_desc: "Absorb 12 plane echo soulfires",
  sq_side_wisp_12_journal: "Twelve wisps return to the anchor; the plane's pulse steadies.",
  sq_side_style_a_title: "Style Trial",
  sq_side_style_a_desc: "Reach combat style A in a single fight",
  sq_side_style_a_journal: "The rhythm of parries and executions is the walker's language.",
  sq_side_dungeon_3_title: "Maze Cleaner",
  sq_side_dungeon_3_desc: "Clear 3 different dungeons",
  sq_side_dungeon_3_journal: "The empty rooms of three mazes all whisper of old wars.",
  sq_side_rematch_title: "Beacon Hunter",
  sq_side_rematch_desc: "Rematch a boss 2 times",
  sq_side_rematch_journal: "The beacon rekindles — proof you still hold the blade.",
  sq_side_cg_half_title: "Illustration Traveler",
  sq_side_cg_half_desc: "Unlock 40% of the CG gallery",
  sq_side_cg_half_journal: "Every CG is a slice of a plane's memory.",
  sq_side_photo_desc: "Use {photoMode} photo mode",
  sq_side_photo_journal: "A snapshot under Miller's lens — even gravity slows for it.",
  sq_side_campfire_all_title: "Six Fires Rested",
  sq_side_campfire_all_desc: "Rest at all 6 campfires",
  sq_side_campfire_all_journal: "Six fires, six stretches of road, one walker's trace.",
  sq_side_lost_scholar_title: "The Lost Scholar",
  sq_side_lost_scholar_desc: "Recover 6 scattered lore fragments",
  sq_side_lost_scholar_journal: "The scholar's notes are whole again - every line a road through the old planes.",
  sq_side_echo_half_title: "Dimensional Resonator",
  sq_side_echo_half_desc: "Unlock 50% of the dimension echoes",
  sq_side_echo_half_journal: "You resonate with the echoes of six planes — the poster wall lights up for you.",
  sq_side_wizard_tour_title: "Academy Tour",
  sq_side_wizard_tour_desc: "Resonate with 3 magic academy echoes",
  sq_side_wizard_tour_journal: "Quidditch, greenhouse, common room — all three doors of the academy knocked upon.",
  sq_side_space_tour_title: "Stellar Equation",
  sq_side_space_tour_desc: "Resonate with 3 interstellar echoes",
  sq_side_space_tour_journal: "Hourglass, bookshelf, docking — the three variables of the equation are in place.",
  sq_side_upside_tour_title: "Upside-Down Survivor",
  sq_side_upside_tour_desc: "Resonate with 3 upside-down echoes",
  sq_side_upside_tour_journal: "Broadcast tower, rift, neon — the wind of 1983 no longer chases you.",
  sq_side_echo_full_title: "Full-Spectrum Walker",
  sq_side_echo_full_desc: "Unlock every dimension echo",
  sq_side_echo_full_journal: "All echoes in frequency — six colors light the poster wall, six dreams wake inside one line of dialogue.",
  sq_side_western_tour_title: "Border Tour",
  sq_side_western_tour_desc: "Resonate with 3 border-past echoes",
  sq_side_western_tour_journal: "Saloon, duel circle, railway — three shots across the border have all resonated.",
  sq_side_gangster_tour_title: "Mob Induction",
  sq_side_gangster_tour_desc: "Resonate with 3 underworld gang echoes",
  sq_side_gangster_tour_journal: "Speakeasy, shrine, warehouse — all three doors of the gang knocked upon.",
  sq_side_scifi_tour_title: "Deep-Space Chronicle",
  sq_side_scifi_tour_desc: "Resonate with 3 deep-space era echoes",
  sq_side_scifi_tour_journal: "Dome, AI, jump gate — the three variables of the sci-fi equation are in place.",
  sq_side_triad_master_title: "Triad in Frequency",
  sq_side_triad_master_desc: "Resonate with every echo of the western, gangster and sci-fi series",
