  start_qk_attack: 'Light / Heavy',
  start_qk_spell: 'Spells 1-4',
  start_qk_weapon: 'Weapon swap',
  start_qk_interact: 'Interact / Talk',
  start_qk_pause: 'Pause / Manual',
