  sq_side_homecoming_wayfare_title: 'The Wayfarer',
  sq_side_homecoming_wayfare_desc: 'Hear all five voices of homecoming — the embers, the bell, the beacon, the tide, and the lantern.',
  sq_side_homecoming_wayfare_journal: 'Those who walk the echoes of homecoming remember every road that leads back to themselves.',
  ach_echo_homecoming_title: 'Wayfarer’s Echo',
  ach_echo_homecoming_desc: 'Resonate with 3 homecoming echoes',
  ach_echo_homecoming_master_title: 'All Roads Home',
  ach_echo_homecoming_master_desc: 'Collect every homecoming echo',
  franchise_homecoming_label: 'Homecoming',
  echo_homecoming_cairn_title: 'Cairn of Embers',
  echo_homecoming_cairn_desc: 'In the Gloom lies a heap of unburnt charcoal and old-name stones — a ghost who lost the road home.',
  echo_homecoming_bell_title: 'The Dawn Bell',
  echo_homecoming_bell_desc: 'A rusted bronze bell in the Radiant, rung by no one, yet it sounds at dusk — the harbor bell the homebound crew agreed upon.',
  echo_homecoming_beacon_title: 'The Second Beacon',
  echo_homecoming_beacon_desc: 'A second beacon blinks out in the deep starsea, broadcasting your name — the road home is never walked alone.',
  echo_homecoming_tide_title: 'The Homecoming Tide',
  echo_homecoming_tide_desc: 'At one low tide the salt sea uncovered a hull beached for years, bow pointed at the planar hub.',
  echo_homecoming_lantern_title: 'The Traveler Lantern',
  echo_homecoming_lantern_desc: 'A lantern that never dies burns at the hub crossroads — those who walked every plane and still long to come home see it, and know they made it back.',
  echo_homecoming_sky_lantern_title: "Lantern Festival · Ascension",
  echo_homecoming_sky_lantern_desc: "The arithmancer lit a paper lantern atop the tower; as it rose through the clouds it wrote the way home across the stars.",
  echo_homecoming_river_lamp_title: "Lantern Festival · River Lamps",
  echo_homecoming_river_lamp_desc: "A thousand river lamps drift over the Abyssal Salt Sea, each pressing into the dark a name that was never said aloud.",
  echo_homecoming_paper_crane_title: "Lantern Festival · Thousand Cranes",
  echo_homecoming_paper_crane_desc: "By the rift sits a girl folding cranes — a thousand made whole, and the lost will find their way home.",
  echo_homecoming_first_snow_title: "Lantern Festival · First Snow",
  echo_homecoming_first_snow_desc: "The first snow fell on the ashes, and it smelled like a meal from long ago — the hearth-fire, the vinegar on the sill.",
  echo_homecoming_last_light_title: "Lantern Festival · The Last Light",
  echo_homecoming_last_light_desc: "In the finale, someone lifts a shattered star-lamp overhead — no light along every plane was ever lit for anyone but you.",
  echo_broken_sword_title: "Middle-earth Echo · The Broken Sword",
  echo_broken_sword_desc: "The hilt of a blade rammed into black stone — a relic of the Last Alliance, and no one dare pull it free.",
  echo_elven_harp_title: "Middle-earth Echo · The Elven Harp",
  echo_elven_harp_desc: "A harp plays itself in a hidden ravine — no one plucks the strings, yet every line of the melody knows the road home.",
  echo_mithril_shard_title: "Middle-earth Echo · The Mithril Shard",
  echo_mithril_shard_desc: "Scattered mithril from the deep mines of Moria — lighter than iron, whiter than silver, and dearer than silence.",
  ach_echo_middle_earth_title: "Whispers of Middle-earth",
  ach_echo_crossover_title: 'The Promise Beyond',
  ach_echo_crossover_desc: 'Collect all three crossover echoes from beyond the poster wall',
  ach_echo_middle_earth_desc: "Collect all four Middle-earth echoes",
  echo_floating_casino_title: "Cyber Neon · The Floating Casino",
  echo_floating_casino_desc: "Neon glowing above the cloud layer — no tables, no chips — everyone who enters wagers themselves, and walks away lighter of soul.",
  echo_black_market_pod_title: "Cyber Neon · The Black Market Pod",
  echo_black_market_pod_desc: "A half-buried trading pod on the trade road — sold by the byte, with the second transaction always unread.",
  echo_rooftop_dojo_title: "Cyber Neon · The Rooftop Dojo",
  echo_rooftop_dojo_desc: "Neon drowns the steel railing in blood-red — a plank platform on a rooftop, no master, no uniforms, just a blade. Come to learn, leave without drawing it.",

