  // W-E10 (Deep Sky Aperture Wave16): Obsidian Obelisk / Broken-Anchor Pilot / Dying Star Hulk
  // Wave18 (Abyssal Mouth voidmaw): The Choir Below / The Anchor / The Dim Hand (W-E11)
