  echo_starport_dealmaker_title: 'The Starport Dealmaker',
  echo_starport_dealmaker_desc: 'The Dealmaker does not bargain with words — he lights a match, slides a glass of wine, and carries what he is owed.',
  echo_starport_rigger_title: 'The Hook-Lantern',
  echo_starport_rigger_desc: 'The lantern that always nods in the hold — one gesture from the foreman and it goes still.',
  echo_starport_navigator_title: 'The Star-Chart Runner',
  echo_starport_navigator_desc: 'The star-chart runner may never have been to the star — he can count every planet\'s exact weight by looking at its outline.',
  echo_void_choir_title: 'The Choir Below',
  echo_void_choir_desc: 'Now and then the abyss turns the surrounding wind into a choir — the modulation is one no mortal voice can reach.',
  echo_void_anchor_title: 'The Anchor and Its Unmooring',
  echo_void_anchor_desc: 'Every heavy anchor that strikes here behaves as if it is surfacing to depart — only when you stand still does it walk itself forward, step by step.',
  echo_void_hand_title: 'The Dim Hand',
  echo_void_hand_desc: 'The hand that reaches out of the abyss never closes on anything — it is only waiting for the warmth it is meant to hold.',
  echo_grain_obelisk_title: 'The Obsidian Obelisk',
  echo_grain_obelisk_desc: 'Nothing survived the crossing but the stone pillar — older than the civilization it fell near.',
  echo_pilot_crash_title: 'Broken-Anchor Pilot',
  echo_pilot_crash_desc: 'His gravity band is still falling in a nervous cycle — the period is right, but it never lands.',
  echo_star_derelict_title: 'The Dying Star Hulk',
  echo_star_derelict_desc: 'A star on its last breath, holding its light in, waiting for someone to read what it is saying.',



