  sq_side_beyond_frames_title: 'Beyond the Frames',
  sq_side_beyond_frames_desc: 'Resonate with all three crossover echoes',
  sq_side_beyond_frames_journal: 'The border is not the edge; the wall is; the echo is not the wall.',
  ach_epitaphs_title: 'Stardust Epitaphs - Torn Pages of the Tome',
  ach_epitaphs_hint: 'When a mother-theme completes, the fire leaves one line in your name.',
  ach_epitaphs_locked: 'This mother-theme is not yet set — a line is waiting behind the lock.',
  ach_ept_wizard: 'The page you close has been yours all along.',
  ach_ept_interstellar: 'The chart has no end; the light keeps the correspondence.',
  ach_ept_upside: 'Deeper you fall, the more clearly you hear yourself.',
  ach_ept_border: "At the border's end, wind; at wind's end, a song of gunpowder.",
  ach_ept_family: 'The old world left no names — only signals and bows.',
  ach_ept_deepspace: 'A ship is the answer echoing against the dark.',
  ach_ept_cyber: 'A thousand names the screens gave; one line was signed by you.',
  ach_ept_samurai: 'The instant of the draw, past and future meet on one blade.',
  ach_ept_cosmic: 'At the end of whispers, the cosmos first understood silence.',
  ach_ept_starport: 'Lanterns turn, cargo sleeps; every port waits for one name.',
  ach_ept_gloom: 'The darkest line in the fog reads: light.',
  ach_ept_radiant: 'The old banner dims; the light remembers them anyway.',
  ach_ept_voidmaw: 'One petal of silence waits at your fingertips for a hundred years.',
  ach_ept_abysssalt: 'The conch withdraws its voice; you exhale the answer back.',
  ach_ept_middle_earth: 'The ring is down; the stones remain; the sword is at rest.',
  ach_ept_homecoming: 'The one who returns is the fire that found its hearth.',
  ach_ept_crossover: 'The poster never finished; the best world is the next reel.',
  ach_echo_keeper_title: 'Keeper of the Gathering Fire',
  ach_echo_keeper_desc: 'All seventeen mother-themes resonate — the fire knows every world',
  lore_pop_trilance_title: 'The Fourth Drop of Wax on the Trilance',
  lore_pop_trilance_text: 'The Trilance lights no one and no thing; it lights only what it has remembered. The three suns take turns laying their shadows across the stele, and after the third one dies there is always one lone drop of wax, seeping down the seam of the stone. They say it is the third sun writing an invitation for whoever comes after — no addressee, only a single line: if you came, the seat at the edge is already yours.',
  lore_pop_glasschoir_title: 'An Octave of the Glass Organ',
  lore_pop_glasschoir_text: 'The Glass Organ sounded once and never again. The pitch was right, the harmony was steady — and yet every pipe ended in silence, so what it played was not music but testimony for some unfinished sentence. The audience dispersed quickly. Only the old man in the last row laughed: this organ is not played for the living.',
  ambient_void_p9: 'A line no one wrote appeared under the candle-shadow: before the Trilance, do not ask which one goes out first — ask which number guest you are.',
  ambient_void_p10: 'You never burned the letter. The three suns fell silent at the same time, for one shared moment, and then went on turning.',
  journal_tab_trilance: 'Starpath · The Trisolar Tide',
  trilance_intro: 'One tide a week, three cards. Whatever Sunscar Stair said is yours to read this week.',
