  hm_title_first_3_minutes: 'First three minutes at the hearth — your opening route',
  hm_body_first_3_minutes: `From ignition to your first small foe brought down — a three-minute route; follow it and you will not get lost.

· 0:00 — Press {interact} to inspect the anchor beacon ahead (blue-white light pillar) — the quest logs itself automatically; follow the golden arrow in the {journal} panel.
· 0:30 — Walk to the edge of the Greywood — your first piece of gear lies in the wooden crate behind the Hearth Elder — glance at it on the way; press {interact} to pick up.
· 1:00 — The first enemy is not charging at you: it is a slow-walker on the right side of the woods — get close and press {interact} to swing — it falls in two or three hits; pick up its dropped shards.
· 1:30 — Shards stow automatically — walk back to the anchor fire and press {interact} at the hearth vendor — trade for your first “Brambleguard Blade”.
· 2:00 — The lantern brightens: a golden arrow to Greyrock Pass appears top-left — the main quest line has lit up.
· 2:30 — Before entering Greyrock Pass, press {help} and skim “First Boss — How Not To Die” — under three minutes, and the boss stops being scary.
· 3:00 — Press {journal} to check the journal: quests / goals / read fragments all live here — lost? Press {minimap}.`,
  hm_title_newcomer_traps: 'First 30 seconds — do these right',
  hm_body_newcomer_traps: `Thirty seconds, six things you will never regret knowing:

· Mouse direction is fixed — it now feels the way it should: scroll up = look up, scroll down = look down; wheel also zooms.
· Don't mash {escape} — each press closes only the topmost layer; stuck in menus? Press {journal}, open the journal, come back out.
· Don't bang on doors — some need lore, some need anchor shards, some need a lit flame — press {help} whenever you are unsure; the journal remembers unsolved symbols.
· Want to see the story first? Press {autoPlay} — autoplay runs the mainline to its end and forks the ending; turn it off if you want the real trip.
· Lost at the doorway? Press {minimap} — the world map shows quest waypoints, POIs and dungeon entrances; follow the gold arrows.
· Don't want to memorize keys? Press {help} — everything you can do is on this page.`,
  hm_title_first_boss_assist: 'First boss · the primer · how not to die',
  hm_body_first_boss_assist: `This is the first fight of your whole trip, not the last one. Survive this one and you are still alive.

· Don't hit yet — stand about 8 paces away and watch it for 20 seconds: the three step-colours (cold-blade white · death-snow red · abyss-grey), the wind-up of each move, how both its energy bars refill. Attacking blind means dying without learning.
· You don't have to drop it in one try — run it to a sliver of health, then step away; it will go wandering and come back to you. "Walk away" is for the living, especially in chapter one.
· Don't bring the heavy weapons ("Heaven-Splinter" and its cousins — long wind-ups); bring something quick that bounces (e.g. "Iron-Feather" — short, fast, stubborn). The boss's first opening is shield-shaped; you want to land hits, not spend your whole opening waiting.
· Don't lean on evasion-tagged gear — evasion is a dice game you play with someone else's dice; learn to stand still, take the hit, and answer.
· When it calls you — look at it for 3 seconds. It is not trying to scare you. It is waking up something inside you.`,
  hm_title_trilance_tip: 'Starpath · Weekly tide — the three details',
  hm_body_trilance_tip: 'A third hand at the Starpath table. Three things you should know first.\n\n'
    + '**Monday** (UTC 00:00) — draws reset weekly. If you came today, the next chance opens on Monday.\n'
    + '**Three cards per draw.** If the three cards match the same tier (all ★1, all ★2, or all ★3), you score an **"Aligned"** — 30% extra souls. The Trisolar Tide is the weekly gamble.\n'
    + 'The daily Flame draw is for today; the weekly tide is for the week. Two systems, two registers.\n'
    + 'Both live under Journal → Starpath · Anchor Flame. Tap to cast, see the three moons land side by side.\n\n'
    + '**Together they give you today and the week ahead** — two lines of reading, two windows on the door.',
  reader_mirror_title: 'The Mirror at the End of the Fire',
  reader_mirror_eyebrow: 'The Reader · Mirror',
  reader_mirror_body: 'When you set down the twentieth volume, the stars step back and leave an open seat. From that moment on, you are not the one who has finished this book — you are the one who, after closing the last page, still sees a fire through the edge of the window. The flame will not die, because reading has always been your own gift to yourself.',
  reader_mirror_reward: 'The Mirror unlocks · +200 souls (once)',
  reader_mirror_made: 'You finished all 20 volumes here. The fire kept a shadow of you.',
  lore_pop_mirror_title: 'The One Who Finished Volume Twenty',
  lore_pop_mirror_text: 'He used the wax his father had left nailing shut. The one who finishes volume twenty stops fearing books; he has learned that the fire does not need to be seen — only remembered.',
  lore_pop_nightwalk_title: 'Father Never Nailed It',
  lore_pop_nightwalk_text: 'The door was not broken. A handful of village children, unseen, replaced the three nailed planks with a piece of ginkgo by daylight. No one asked why; the children already knew.',
